-- Passos e escolhas das situações (gerado de src/lib/seed.ts). Idempotente.
begin;
update situation set summary='Seus amigos oferecem um vape numa festa. E agora?', title='Pressão social', published=true where slug='pressao-social';
delete from scenario_step where situation_id=(select id from situation where slug='pressao-social');
with st as (insert into scenario_step (situation_id, position, body, question) select id, 0, 'É sábado à noite e você está com a sua turma. Alguém tira um vape do bolso, dá uma tragada e passa pra você: "Relaxa, é só sabor de fruta, não faz nada". Todo mundo olha. Você sente aquele frio na barriga de não querer parecer careta.

Vale saber: a maioria dos vapes tem nicotina — muitas vezes em quantidade alta — mesmo quando o cheiro é doce. A nicotina age rápido no cérebro adolescente, que ainda está em formação, e pode gerar dependência.', 'O que você faz?' from situation where slug='pressao-social' returning id)
insert into choice (step_id, position, label, feedback, trail, next_step) select st.id, v.p, v.l, v.f, v.t::trail_key, v.n::next_step from st, (values (0, 'Recuso com uma frase curta: "Não, valeu" e mudo de assunto.', 'Boa! Uma recusa simples e segura funciona muito bem. Você não precisa se justificar. Amigos de verdade respeitam um "não".', 'prevencao', 'confianca'), (1, 'Aceito só uma vez para não ficar de fora.', 'Entendemos — a vontade de pertencer é real. Mas "só uma vez" é como muita dependência começa. Da próxima, experimente ter uma frase pronta ou um plano de saída (ex.: "vou pegar água").', 'prevencao', 'confianca'), (2, 'Saio de perto e chamo alguém de confiança.', 'Ótima escolha. Afastar-se da situação e buscar apoio mostra autocuidado. Conversar com alguém de confiança ajuda a se preparar para as próximas vezes.', 'prevencao', 'confianca')) as v(p,l,f,t,n);
update situation set summary='Você viu vídeos sobre vape e ficou curioso(a).', title='Curiosidade', published=true where slug='curiosidade';
delete from scenario_step where situation_id=(select id from situation where slug='curiosidade');
with st as (insert into scenario_step (situation_id, position, body, question) select id, 0, 'Nas redes, aparece gente fazendo nuvens de fumaça e truques. Parece inofensivo e até divertido. Você fica pensando: "Será que é tão ruim assim?"

Fatos: no Brasil, a venda de cigarros eletrônicos é proibida pela Anvisa. Os líquidos podem conter nicotina, metais e substâncias que irritam os pulmões. Conteúdo nas redes muitas vezes é publicidade disfarçada.', 'Qual é o seu próximo passo?' from situation where slug='curiosidade' returning id)
insert into choice (step_id, position, label, feedback, trail, next_step) select st.id, v.p, v.l, v.f, v.t::trail_key, v.n::next_step from st, (values (0, 'Procuro informação em fontes confiáveis (Ministério da Saúde, INCA).', 'Excelente! Curiosidade é ótima quando vem com boas fontes. Você está tomando uma decisão informada.', 'prevencao', 'confianca'), (1, 'Experimento para ver como é.', 'A curiosidade é natural, mas experimentar expõe você à nicotina e a outros riscos. Se tiver dúvidas sobre saúde, a UBS mais próxima pode conversar com você sem julgamento.', 'prevencao', 'ubs'), (2, 'Pergunto para um adulto de confiança o que ele sabe.', 'Boa ideia. Conversar abre espaço para tirar dúvidas e pensar junto, sem pressão.', 'prevencao', 'confianca')) as v(p,l,f,t,n);
update situation set summary='Você já usa e está difícil parar.', title='Dificuldade para parar', published=true where slug='dificuldade-para-parar';
delete from scenario_step where situation_id=(select id from situation where slug='dificuldade-para-parar');
with st as (insert into scenario_step (situation_id, position, body, question) select id, 0, 'Você começou "só de vez em quando", mas agora sente vontade várias vezes ao dia. Já tentou parar e ficou irritado(a), ansioso(a) ou com dificuldade de concentração.

Isso não é fraqueza: são sinais comuns de dependência de nicotina. A boa notícia é que dá para parar, e você não precisa fazer isso sozinho(a). O SUS oferece apoio gratuito.', 'O que você gostaria de fazer agora?' from situation where slug='dificuldade-para-parar' returning id)
insert into choice (step_id, position, label, feedback, trail, next_step) select st.id, v.p, v.l, v.f, v.t::trail_key, v.n::next_step from st, (values (0, 'Quero conversar com alguém de confiança sobre isso.', 'Esse é um passo corajoso. Contar para alguém de confiança deixa o caminho mais leve. Você pode começar com: "Preciso de ajuda com uma coisa".', 'apoio', 'confianca'), (1, 'Quero saber onde buscar ajuda profissional.', 'Ótimo. A UBS (Unidade Básica de Saúde) oferece acompanhamento gratuito para quem quer parar com a nicotina. Você também pode ligar no Disque Saúde 136.', 'apoio', 'ubs'), (2, 'Ainda não sei se quero parar.', 'Tudo bem não ter certeza. Que tal observar quando a vontade aparece? Informação ajuda a decidir. O Disque Saúde 136 tira dúvidas de forma gratuita e sigilosa.', 'apoio', 'disque136')) as v(p,l,f,t,n);
commit;
